    %    secf = { f for f ∈ fset if `∂¹`_e,f = -1 }
    %    
    %    OppositeVertices(e) = tuple(firv_1, secv_1) where e ∈ E,
    %    firf, secf = OppositeFaces(e),
    %    firv = Vertices(firf) \ Vertices(e),
    %    secv = Vertices(secf) \ Vertices(e)
    %    
    %    OppositeVertices(i, j) = tuple(firv_1, secv_1) where i,j ∈ V,
    %    firf, secf = OrientedOppositeFaces(i, j),
    %    firv = Vertices(firf) \ {i, j},
    %    secv = Vertices(secf) \ {i, j}
    %    
    %    FaceIndex(i,j,k) = fset_1  where i,j,k ∈ V,
    %    ufv = `B¹`ᵀ `B⁰`ᵀ,
    %    iface = faceset(NonZeros(ufv  IndicatorVector({i}))),
    %    jface = faceset(NonZeros(ufv  IndicatorVector({j}))),
    %    kface = faceset(NonZeros(ufv IndicatorVector({k}))),
    %    fset = iface ∩ jface ∩ kface
    %    
    %    OrientedVertices(i,j,k) = NeighborVerticesInFace(f, i)  where i,j,k ∈ V,
    %    f = FaceIndex(i, j, k)
    %    
        dimv_0 = M.n_vertices();
        dime_0 = M.n_edges();
        dimf_0 = M.n_faces();
        [V, E, F] = M.ElementSets();
        function output = FundamentalMeshAccessors(M)
        % output = FundamentalMeshAccessors(M)
        %
        %    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector  from MeshConnectivity
        %    
        %    M : FaceMesh 
        %    
        %    V, E, F = ElementSets( M )
        %    dee0, dee1 = BoundaryMatrices(M) 
        %    B0, B1 = UnsignedBoundaryMatrices(M)
        %    B0T = B0ᵀ
        %    B1T = B1ᵀ
        %    
        %    Vertices(S) = S₁ where S: CellularSet
        %    Edges(S)    = S₂ where S: CellularSet 
        %    Faces(S)    = S₃ where S: CellularSet
        %     
        %    Vertices(f) = vertexset(NonZeros(B0 (B1 IndicatorVector({f})))) where f ∈ F
        %    Vertices(G) = vertexset(NonZeros(B0 (B1 IndicatorVector(G)))) where G ⊂ F
        %    Vertices(e) = vertexset(NonZeros(B0 IndicatorVector({e}))) where e ∈ E
        %    Vertices(H) = vertexset(NonZeros(B0 IndicatorVector(H))) where H ⊂ E
        %     
        %    Edges(v) = edgeset(NonZeros(B0T IndicatorVector({v}))) where v ∈ V
        %    Edges(f) = edgeset(NonZeros(B1 IndicatorVector({f}))) where f ∈ F
        %    
        %    Faces(v) = faceset(NonZeros(B1T (B0T IndicatorVector({v})))) where v ∈ V
        %    Faces(e) = faceset(NonZeros(B1T IndicatorVector({e}))) where e ∈ E
            dimv_0 = M.n_vertices();
            dime_0 = M.n_edges();
            dimf_0 = M.n_faces();
            [V, E, F] = M.ElementSets();
            [dee0, dee1] = M.BoundaryMatrices();
            [B0, B1] = M.UnsignedBoundaryMatrices();
            % B0T = B0ᵀ
            B0T = B0';
            % B1T = B1ᵀ
            B1T = B1';
            function [ret] = Vertices(S)
                ret = S(1);
            end
            function [ret_1] = Edges(S)
                ret_1 = S(2);
            end
            function [ret_2] = Faces(S)
                ret_2 = S(3);
            end
            function [ret_3] = Vertices_0(f)
                assert(numel(f) == 1);
                assert( ismember(f, F) );
                ret_3 = NonZeros(B0 * (B1 * indicator([f], M.n_faces())));
            end
            function [ret_4] = Vertices_1(G)
                ret_4 = NonZeros(B0 * (B1 * indicator(G, M.n_faces())));
            end
            function [ret_5] = Vertices_2(e)
                assert(numel(e) == 1);
                assert( ismember(e, E) );
                ret_5 = NonZeros(B0 * indicator([e], M.n_edges()));
            end
            function [ret_6] = Vertices_3(H)
                ret_6 = NonZeros(B0 * indicator(H, M.n_edges()));
            end
            function [ret_7] = Edges_0(v)
                assert(numel(v) == 1);
                assert( ismember(v, V) );
                ret_7 = NonZeros(B0T * indicator([v], M.n_vertices()));
            end
            function [ret_8] = Edges_1(f)
                assert(numel(f) == 1);
                assert( ismember(f, F) );
                ret_8 = NonZeros(B1 * indicator([f], M.n_faces()));
            end
            function [ret_9] = Faces_0(v)
                assert(numel(v) == 1);
                assert( ismember(v, V) );
                ret_9 = NonZeros(B1T * (B0T * indicator([v], M.n_vertices())));
            end
            function [ret_10] = Faces_1(e)
                assert(numel(e) == 1);
                assert( ismember(e, E) );
                ret_10 = NonZeros(B1T * indicator([e], M.n_edges()));
            end
            output.V = V;
            output.E = E;
            output.F = F;
            output.dee0 = dee0;
            output.dee1 = dee1;
            output.B0 = B0;
            output.B1 = B1;
            output.B0T = B0T;
            output.B1T = B1T;
            output.Vertices = @Vertices;
            output.Edges = @Edges;
            output.Faces = @Faces;
            output.Vertices_0 = @Vertices_0;
            output.Vertices_1 = @Vertices_1;
            output.Vertices_2 = @Vertices_2;
            output.Vertices_3 = @Vertices_3;
            output.Edges_0 = @Edges_0;
            output.Edges_1 = @Edges_1;
            output.Faces_0 = @Faces_0;
            output.Faces_1 = @Faces_1;
            output.M = M;
        end
        FundamentalMeshAccessors_ = FundamentalMeshAccessors(M);
        Vertices = @FundamentalMeshAccessors_.Vertices;
        Vertices_0 = @FundamentalMeshAccessors_.Vertices_0;
        Vertices_1 = @FundamentalMeshAccessors_.Vertices_1;
        Vertices_2 = @FundamentalMeshAccessors_.Vertices_2;
        Vertices_3 = @FundamentalMeshAccessors_.Vertices_3;
        Edges = @FundamentalMeshAccessors_.Edges;
        Edges_0 = @FundamentalMeshAccessors_.Edges_0;
        Edges_1 = @FundamentalMeshAccessors_.Edges_1;
        Faces = @FundamentalMeshAccessors_.Faces;
        Faces_0 = @FundamentalMeshAccessors_.Faces_0;
        Faces_1 = @FundamentalMeshAccessors_.Faces_1;
        [dee0, dee1] = M.BoundaryMatrices();
        [B0, B1] = M.UnsignedBoundaryMatrices();
        % `B⁰ᵀ` = `B⁰`ᵀ
        B0T = B0';
        % `B¹ᵀ` = `B¹`ᵀ
        B1T = B1';
        function [ret] = VertexOneRing(v)
            assert(numel(v) == 1);
            assert( ismember(v, V) );
            ret = setdiff(NonZeros(B0 * (B0T * indicator([v], M.n_vertices()))), [v]);
        end
        function [ret_1] = VertexOneRing_0(v)
            ret_1 = setdiff(NonZeros(B0 * (B0T * indicator(v, M.n_vertices()))), v);
        end
        function [ret_2] = EdgeIndex(i, j)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            % eset = Edges(i) ∩ Edges(j)
            eset = intersect(Edges_0(i), Edges_0(j));
            ret_2 = eset(1);
        end
        function [ret_3, ret_4] = NeighborVerticesInFace(f, v)
            assert(numel(f) == 1);
            assert(numel(v) == 1);
            assert( ismember(v, V) );
            assert( ismember(f, F) );
            % es = edgeset(NonZeros(`∂¹` IndicatorVector({f})))
            es = NonZeros(dee1 * indicator([f], M.n_faces()));
            % nes = { s for s ∈ es if `∂⁰`_v,s != 0 }
            NeighborVerticesInFaceset_1 = [];
            range = es;
            for index = 1:length(range)
                s = range(index);
                if dee0(v, s) ~= 0
                    NeighborVerticesInFaceset_1 = [NeighborVerticesInFaceset_1; s];
                end
            end
            nes = NeighborVerticesInFaceset_1;
            % eset1 = { e for e ∈ nes if `∂¹`_e,f `∂⁰`_v,e = -1}
            NeighborVerticesInFaceset_2 = [];
            range_1 = nes;
            for index_1 = 1:length(range_1)
                e = range_1(index_1);
                if dee1(e, f) * dee0(v, e) == -1
                    NeighborVerticesInFaceset_2 = [NeighborVerticesInFaceset_2; e];
                end
            end
            eset1 = NeighborVerticesInFaceset_2;
            % vset1 = vertexset(NonZeros(`B⁰` IndicatorVector(eset1))) - {v}
            vset1 = setdiff(NonZeros(B0 * indicator(eset1, M.n_edges())), [v]);
            % eset2 = { e for e ∈ nes if `∂¹`_e,f `∂⁰`_v,e = 1 }
            NeighborVerticesInFaceset_4 = [];
            range_2 = nes;
            for index_2 = 1:length(range_2)
                e = range_2(index_2);
                if dee1(e, f) * dee0(v, e) == 1
                    NeighborVerticesInFaceset_4 = [NeighborVerticesInFaceset_4; e];
                end
            end
            eset2 = NeighborVerticesInFaceset_4;
            % vset2 = vertexset(NonZeros(`B⁰` IndicatorVector(eset2))) - {v}
            vset2 = setdiff(NonZeros(B0 * indicator(eset2, M.n_edges())), [v]);
            tuple = [vset1(1),vset2(1)];
            ret_3 = tuple(1);
            ret_4 = tuple(2);
        end
        function [ret_5] = NextVerticeInFace(f, v)
            assert(numel(f) == 1);
            assert(numel(v) == 1);
            assert( ismember(v, V) );
            assert( ismember(f, F) );
            % eset = { e for e ∈ Edges(f) if `∂¹`_e,f `∂⁰`_v,e = -1}
            NextVerticeInFaceset_0 = [];
            range_3 = Edges_1(f);
            for index_3 = 1:length(range_3)
                e = range_3(index_3);
                if dee1(e, f) * dee0(v, e) == -1
                    NextVerticeInFaceset_0 = [NextVerticeInFaceset_0; e];
                end
            end
            eset = NextVerticeInFaceset_0;
            % vset = Vertices(eset) - {v}
            vset = setdiff(Vertices_3(eset), [v]);
            ret_5 = vset(1);
        end
        function [ret_6, ret_7, ret_8] = OrientedVertices(f)
            assert(numel(f) == 1);
            assert( ismember(f, F) );
            % vs = Vertices(f)
            vs = Vertices_0(f);
            [i, j] = NeighborVerticesInFace(f, vs(1));
            tuple_1 = [vs(1),i,j];
            ret_6 = tuple_1(1);
            ret_7 = tuple_1(2);
            ret_8 = tuple_1(3);
        end
        function [ret_9, ret_10, ret_11, ret_12] = Diamond(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            tuple_2 = [Vertices_2(e),[e],Faces_1(e),[]];
            ret_9 = tuple_2(1);
            ret_10 = tuple_2(2);
            ret_11 = tuple_2(3);
            ret_12 = tuple_2(4);
        end
        function [ret_13, ret_14] = OrientedOppositeFaces(i, j)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            % e = EdgeIndex(i, j)
            e = EdgeIndex(i, j);
            % fset = Faces(e)
            fset = Faces_1(e);
            % firf = { f for f ∈ fset if `∂¹`_e,f `∂⁰`_i,e = -1 }
            OrientedOppositeFacesset_0 = [];
            range_4 = fset;
            for index_4 = 1:length(range_4)
                f = range_4(index_4);
                if dee1(e, f) * dee0(i, e) == -1
                    OrientedOppositeFacesset_0 = [OrientedOppositeFacesset_0; f];
                end
            end
            firf = OrientedOppositeFacesset_0;
            % secf = fset - firf
            secf = setdiff(fset, firf);
            tuple_3 = [firf(1),secf(1)];
            ret_13 = tuple_3(1);
            ret_14 = tuple_3(2);
        end
        function [ret_15, ret_16] = OppositeFaces(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            % fset = Faces(e)
            fset = Faces_1(e);
            % firf = { f for f ∈ fset if `∂¹`_e,f = 1 }
            OppositeFacesset_0 = [];
            range_5 = fset;
            for index_5 = 1:length(range_5)
                f = range_5(index_5);
                if dee1(e, f) == 1
                    OppositeFacesset_0 = [OppositeFacesset_0; f];
                end
            end
            firf = OppositeFacesset_0;
            % secf = { f for f ∈ fset if `∂¹`_e,f = -1 }
            OppositeFacesset_1 = [];
            range_6 = fset;
            for index_6 = 1:length(range_6)
                f = range_6(index_6);
                if dee1(e, f) == -1
                    OppositeFacesset_1 = [OppositeFacesset_1; f];
                end
            end
            secf = OppositeFacesset_1;
            tuple_4 = [firf(1),secf(1)];
            ret_15 = tuple_4(1);
            ret_16 = tuple_4(2);
        end
        function [ret_17, ret_18] = OppositeVertices(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            [firf, secf] = OppositeFaces(e);
            % firv = Vertices(firf) \ Vertices(e)
            firv = setdiff(Vertices_0(firf), Vertices_2(e));
            % secv = Vertices(secf) \ Vertices(e)
            secv = setdiff(Vertices_0(secf), Vertices_2(e));
            tuple_5 = [firv(1),secv(1)];
            ret_17 = tuple_5(1);
            ret_18 = tuple_5(2);
        end
        function [ret_19, ret_20] = OppositeVertices_0(i, j)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            [firf, secf] = OrientedOppositeFaces(i, j);
            % firv = Vertices(firf) \ {i, j}
            firv = setdiff(Vertices_0(firf), [i, j]);
            % secv = Vertices(secf) \ {i, j}
            secv = setdiff(Vertices_0(secf), [i, j]);
            tuple_6 = [firv(1),secv(1)];
            ret_19 = tuple_6(1);
            ret_20 = tuple_6(2);
        end
        function [ret_21] = FaceIndex(i, j, k)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert(numel(k) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            assert( ismember(k, V) );
            % ufv = `B¹`ᵀ `B⁰`ᵀ
            ufv = B1' * B0';
            % iface = faceset(NonZeros(ufv  IndicatorVector({i})))
            iface = NonZeros(ufv * indicator([i], M.n_vertices()));
            % jface = faceset(NonZeros(ufv  IndicatorVector({j})))
            jface = NonZeros(ufv * indicator([j], M.n_vertices()));
            % kface = faceset(NonZeros(ufv IndicatorVector({k})))
            kface = NonZeros(ufv * indicator([k], M.n_vertices()));
            % fset = iface ∩ jface ∩ kface
            fset = intersect(iface, intersect(jface, kface));
            ret_21 = fset(1);
        end
        function [ret_22, ret_23] = OrientedVertices_0(i, j, k)
            assert(numel(i) == 1);
            assert(numel(j) == 1);
            assert(numel(k) == 1);
            assert( ismember(i, V) );
            assert( ismember(j, V) );
            assert( ismember(k, V) );
            % f = FaceIndex(i, j, k)
            f = FaceIndex(i, j, k);
            tuple_7 = NeighborVerticesInFace(f, i);
            ret_22 = tuple_7(1);
            ret_23 = tuple_7(2);
        end
        output.V = V;
        output.E = E;
        output.F = F;
        output.dee0 = dee0;
        output.dee1 = dee1;
        output.B0 = B0;
        output.B1 = B1;
        output.B0T = B0T;
        output.B1T = B1T;
        output.VertexOneRing = @VertexOneRing;
        output.VertexOneRing_0 = @VertexOneRing_0;
        output.EdgeIndex = @EdgeIndex;
        output.NeighborVerticesInFace = @NeighborVerticesInFace;
        output.NextVerticeInFace = @NextVerticeInFace;
        output.OrientedVertices = @OrientedVertices;
        output.Diamond = @Diamond;
        output.OrientedOppositeFaces = @OrientedOppositeFaces;
        output.OppositeFaces = @OppositeFaces;
        output.OppositeVertices = @OppositeVertices;
        output.OppositeVertices_0 = @OppositeVertices_0;
        output.FaceIndex = @FaceIndex;
        output.OrientedVertices_0 = @OrientedVertices_0;
        output.M = M;
    end
    Neighborhoods_ = Neighborhoods(M);
    VertexOneRing = @Neighborhoods_.VertexOneRing;
    VertexOneRing_0 = @Neighborhoods_.VertexOneRing_0;
    Faces = @Neighborhoods_.Faces;
    Faces_0 = @Neighborhoods_.Faces_0;
    Faces_1 = @Neighborhoods_.Faces_1;
    NeighborVerticesInFace = Neighborhoods_.NeighborVerticesInFace;
    function [ret] = UpdateStep(i, j, k, d)
        d = reshape(d,[],1);
        dim_1 = size(d, 1);
        assert(numel(i) == 1);
        assert(numel(j) == 1);
        assert(numel(k) == 1);
        assert( size(d,1) == dim_1 );
        assert( ismember(i, V) );
        assert( ismember(j, V) );
        assert( ismember(k, V) );

        % X = [x_j-x_i x_k-x_i]
        X_0 = [[reshape(x(j,:)' - x(i,:)', [3, 1]), reshape(x(k,:)' - x(i,:)', [3, 1])]];
        X = X_0;

        % t = [d_j d_k]ᵀ
        t_0 = zeros(1, 2);
        t_0(1,:) = [d(j), d(k)];
        t = t_0';

        % Q = (XᵀX)⁻¹
        Q = inv((X' * X));

        % `1` = [1 ; 1]
        num1_0 = zeros(2, 1);
        num1_0(1,:) = [1];
        num1_0(2,:) = [1];
        num1 = num1_0;

        % p = (`1`ᵀQt + sqrt((`1`ᵀQt)² - `1`ᵀQ`1` ⋅ (tᵀQt - 1)))/ (`1`ᵀQ`1`)
        p = (num1' * Q * t + sqrt((num1' * Q * t).^2 - num1' * Q * num1 * (t' * Q * t - 1))) / (num1' * Q * num1);

        % n = XQ(t- p ⋅`1`)
        n = X * Q * (t - p * num1);

        % s = QXᵀn
        s = Q * X' * n;
        if (s(1, 1) < 0) && (s(2, 1) < 0)
            ret = p;
        else
            ret = min(d(j) + norm(x(j,:)' - x(i,:)', 2), d(k) + norm(x(k,:)' - x(i,:)', 2));
        end
    end

    function [ret_1] = GetNextLevel(U)
        dim_2 = size(U, 1);
        % s = ∪_i U_i
        union_0 = [];
        for i = 1:size(U,1)
            union_0 = union(union_0, U{i});
        end
        s = union_0;

        % v = VertexOneRing(s)
        v = VertexOneRing_0(s);
        ret_1 = setdiff(v, s);
    end

    function [ret_2] = GetRangeLevel(U, a, b)
        dim_3 = size(U, 1);
        assert(numel(a) == 1);
        assert(numel(b) == 1);

        union_1 = [];
        for i = a:b
            union_1 = union(union_1, U{i});
        end
        ret_2 = union_1;
    end

    function [ret_3] = GetLevelSequence(U)
        dim_4 = size(U, 1);
        % next = GetNextLevel(U)
        next = GetNextLevel(U);
        if size(next, 1) ~= 0
            seq = U
            seq.add(next)
            ret = seq;
        else
            ret = U;
        end
    end

    output.V = V;
    output.E = E;
    output.F = F;
    output.UpdateStep = @UpdateStep;
    output.GetNextLevel = @GetNextLevel;
    output.GetRangeLevel = @GetRangeLevel;
    output.GetLevelSequence = @GetLevelSequence;
    output.M = M;    
    output.x = x;
end
